lessons=json.loads(LESSONS.read_text()); steps=json.loads(STEPS.read_text()); catalog=json.loads(CATALOG.read_text())
step_map={s['lesson_id']:s for s in steps['stepsets']}
changed=0
for course in lessons['courses']:
    cid=course.get('course_id')
    if cid not in COURSE_DATA: continue
    title,tags,description,lesson_specs=COURSE_DATA[cid]
    course['course_title']=title; course['description']=description
    course['prerequisites']=course.get('prerequisites') or ['course_b_1']
    for lesson, values in zip(course['lessons'],lesson_specs):
        new_title, subtitle, outline = values
        outcome = subtitle
        lesson['title']=new_title; lesson['subtitle']=subtitle
        lesson['tags']=tags
        lesson['content']=[
          {'kind':'intro','text':f"Кун Кру объясняет сцену «{new_title}» через реальный бытовой момент: {subtitle.rstrip('.').lower()}."},
          {'kind':'outline','text':outline},
          {'kind':'apply','text':f"Проговори «{new_title}» как короткий диалог: сначала ситуация, потом одна просьба и один ответ."},
        ]
        lesson['outcomes']=[outcome]
        lesson['prerequisites']=(course['prerequisites'] if lesson['order']==1 else [f"{cid}_l{lesson['order']-1}"]) if not lesson.get('prerequisites') else lesson['prerequisites']
        step=step_map[lesson['lesson_id']]
        contextual_tip={'kind':'tip','text':f"Сцена «{new_title}»: {outline}",'order':1}
        if step['items'] and step['items'][0].get('kind')=='tip':
            step['items'][0]=contextual_tip
        else:
            step['items'].insert(0,contextual_tip)
        for index,item in enumerate(step['items'],1):
            item['order']=index
        step['hints']=[f"Держи в голове момент «{new_title}»: эта фраза нужна именно здесь, а не просто потому, что тема рядом."]
        lesson['card_count']=len(step['items'])
        changed+=1
for course in catalog:
    cid=course.get('id')
    if cid in COURSE_DATA:
        _,tags,description,_=COURSE_DATA[cid]
        course['description']=description
        course['lesson_count']=len(next(c for c in lessons['courses'] if c['course_id']==cid)['lessons'])
        course['learning_outcomes']=[{'type':'Ситуационный flow','count':course['lesson_count']},{'type':'Контекстные repair/exit branches','count':course['lesson_count']}]
LESSONS.write_text(json.dumps(lessons,ensure_ascii=False,indent=2)+'\n')
STEPS.write_text(json.dumps(steps,ensure_ascii=False,indent=2)+'\n')
CATALOG.write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n')
print('updated lessons:',changed)
